-- 0020 — Catálogo dobrado: 228 cotas em 11 categorias (era 105 em 10).
-- Seguro para re-executar: reescreve cada item pelo id (não mexe em `active`).
--
-- Os sorts da 0019 iam de 10 em 10 (10…1050); aqui eles viram 100…10500 (×10, só na
-- primeira execução) e cada cota nova entra logo depois da última da sua categoria
-- (ex.: Lua de mel termina em 1300 → novas em 1301…1312). A categoria nova,
-- Tecnologia e lazer, fica entre Casa e decoração e Para o futuro (8851…).
-- Não reaplique a 0019 depois desta: ela devolveria os sorts antigos.
--
-- Fotos: Pexels (licença Pexels: uso comercial livre, sem atribuição obrigatória),
-- servidas pelo próprio Noivar em /assets/presentes. image_source = página de origem.
-- Aplique no SQL Editor do Supabase junto com o deploy que traz as fotos novas.

update public.gift_catalog set sort = sort * 10
  where (select max(sort) from public.gift_catalog) < 2000;

on conflict (id) do update set
  category     = excluded.category,
  title        = excluded.title,
  description  = excluded.description,
  price        = excluded.price,
  image        = excluded.image,
  image_source = excluded.image_source,
  sort         = excluded.sort;
